import type { GameOverview } from './api/gameOverview'
import { officialArtworkUrl } from './officialArtwork'

// All URLs are generated by Vite from checked-in public game artwork.
const files = import.meta.glob<string>(['../assets/skland/*.png', '../assets/skland/*.avif'], {
  eager: true,
  query: '?url&no-inline',
  import: 'default',
})
export type OverviewArt = {
  src: string
  presentation?: 'official-logo' | 'official-title-icon'
  tone: 'light-ink' | 'dark-ink' | 'color'
  kind: 'icon' | 'map' | 'landscape' | 'cover'
  fallback?: OverviewArt
}
// Only neutral UI symbols may invert. Medal tiers, room colors and map artwork
// carry game semantics and must keep their original colors.
const colorIcons = new Set([
  'ak-logoBase',
  'ak-logoResist',
  'ak-main-task-over',
  'ak-day-common',
  'ak-day-challenge',
  'ef-control',
  'ef-glory-certify',
  'ef-build-domain_1',
  'ef-build-domain_2',
  'ef-bill-domain_1',
  'ef-bill-domain_2',
  'ef-stock-empty',
  'ef-stock-full',
  'ef-monolith-unearned',
  'ef-manufacture',
  'ef-plant',
  'ef-reception',
  'ef-medalLevel1',
  'ef-medalLevel2',
  'ef-medalLevel3',
])
const art = (key: string, kind: OverviewArt['kind'] = 'icon'): OverviewArt | undefined => {
  const src = files[`../assets/skland/${key}.png`] ?? files[`../assets/skland/${key}.avif`]
  return src
    ? {
        src,
        kind,
        presentation: key.startsWith('ak-title-')
          ? 'official-title-icon'
          : key === 'ak-logoBase'
            ? 'official-logo'
            : undefined,
        tone:
          kind !== 'icon' ||
          colorIcons.has(key) ||
          key.startsWith('ef-war-') ||
          key.startsWith('ef-growth-')
            ? 'color'
            : key.startsWith('ak-') || key === 'ef-regionalDevelopment'
              ? 'light-ink'
              : 'dark-ink',
      }
    : undefined
}
export const growthArt = (id: string) => art(`ef-growth-${id}`)
