export function metricArt(game: string, key: string) {
  const id =
    game === 'arknights' ? akMetrics[key] : game === 'endfield' ? efMetrics[key] : undefined
  return id ? art(`${game === 'arknights' ? 'ak' : 'ef'}-${id}`) : undefined
}
