const rooms: Record<string, string> = {
  endfieldControl: 'control',
  endfieldManufacture1: 'manufacture',
  endfieldManufacture2: 'manufacture',
  endfieldManufacture: 'manufacture',
  endfieldPlant1: 'plant',
  endfieldPlant: 'plant',
  endfieldReception: 'reception',
}
type SectionItem = NonNullable<GameOverview['sections']>[number]['items'][number]
function localFacilityArt(
  section: string,
  item: Pick<SectionItem, 'id' | 'nameKey' | 'operatorId'>,
) {
  if (item.operatorId) return undefined
  if (section === 'endfieldSpaceship')
    return rooms[item.nameKey ?? ''] ? art(`ef-${rooms[item.nameKey!]}`) : undefined
  if (section.startsWith('endfieldExploration')) {
    const id = item.id.split(':')[1]
    // indie_dg007 shares the official map02_lv004 artwork; unknown IDs remain text-only.
    return id ? art(`ef-${id === 'indie_dg007' ? 'map02_lv004' : id}`, 'map') : undefined
  }
  if (section === 'endfieldDomains' || section === 'endfieldSettlements') {
    const id = item.id.split(':')[0]
    return id === 'domain_1' || id === 'domain_2' ? art(`ef-${id}`, 'landscape') : undefined
  }
  const variant =
    section === 'arknightsTower'
      ? 'climb_tower/icon'
      : section === 'arknightsCampaign'
        ? 'campaign/zone_icon'
        : null
  if (variant && item.id)
    return {
      src: `https://web.hycdn.cn/arknights/game/assets/game_mode/${variant}/${encodeURIComponent(item.id)}.png`,
      kind: 'icon' as const,
      tone: 'light-ink' as const,
    }
  return sectionArt(section)
}

// The upstream item owns its cover; local ID maps and section symbols are fallbacks.
export function facilityArt(
  section: string,
  item: Pick<SectionItem, 'id' | 'nameKey' | 'operatorId' | 'artworkUrl'>,
): OverviewArt | undefined {
  if (item.operatorId) return undefined
  const generic = sectionArt(section)
  const local = localFacilityArt(section, item)
  const fallback = local
    ? { ...local, fallback: local.src !== generic?.src ? generic : undefined }
    : generic
  const src = officialArtworkUrl(item.artworkUrl)
  return src ? { src, kind: 'cover', tone: 'color', fallback } : fallback
}

export const warEchoesArt = (key: string) => {
  const image = art(`ef-war-${key}`)
  return image && /^star-[0-3]$/.test(key) ? { ...image, tone: 'light-ink' as const } : image
}

export const developmentArt = (key: string) => art(`ef-${key}`)

// Official Endfield CharElementIcon / CharPotentialIcon artwork.
const endfieldElements: Record<string, [string, string]> = {
  物理: ['physical', '#888'],
  Physical: ['physical', '#888'],
  灼热: ['fire', '#ff623d'],
  Heat: ['fire', '#ff623d'],
  电磁: ['electric', '#ffc000'],
  Electric: ['electric', '#ffc000'],
  寒冷: ['ice', '#21c6d0'],
  Cryo: ['ice', '#21c6d0'],
  自然: ['nature', '#9eda23'],
  Nature: ['nature', '#9eda23'],
}
export function endfieldPortraitBadge(
  kind: 'element' | 'potential' | 'profession',
  value: string | number | null,
) {
  if (value == null) return undefined
  if (kind === 'profession') {
    const profession = endfieldProfessions[String(value)]
    const image = profession ? art(`ef-char-profession-${profession}`) : undefined
    return image ? { ...image, tone: 'color' as const, background: '#444' } : undefined
  }
  const element = kind === 'element' ? endfieldElements[String(value)] : undefined
  if (kind === 'element' && !element) return undefined
  const image = art(`ef-char-${kind}-${element?.[0] ?? value}`)
  return image ? { ...image, tone: 'color' as const, background: element?.[1] } : undefined
}

const endfieldProfessions: Record<string, string> = {
  近卫: 'guard',
  Guard: 'guard',
  重装: 'defender',
  Defender: 'defender',
  辅助: 'supporter',
  Supporter: 'supporter',
  术师: 'caster',
  Caster: 'caster',
  突击: 'striker',
  Striker: 'striker',
  先锋: 'vanguard',
  Vanguard: 'vanguard',
}

// DungeonRecordCard uses rarity, not evolvePhase, for its bottom color strip.
const endfieldRarityColors: Record<string, string> = {
  '1': '#b2b2b2',
  '2': '#b4d945',
  '3': '#33c2ff',
  '4': '#b380ff',
  '5': '#ffcc00',
  '6': '#ff7100',
}
export const endfieldRarityColor = (rarity: string | number | null | undefined) =>
  rarity == null ? undefined : endfieldRarityColors[String(rarity).replace(/^rarity_/, '')]

export const gloryArt = (kind: 'empty' | 'certify') => art(`ef-glory-${kind}`)
